    # Search for the 'Archives' widget using various methods since it might not have a specific role
    # First, try to find any element with text containing 'Archives'
    archives_element = page.get_by_text('Archives', exact=False)
    if await archives_element.count() > 0:
        # If found, assume it's the widget and look for the 'June 2024' link within it or nearby
        june_link = page.get_by_role('link', name='June 2024', exact=False)
        if await june_link.count() > 0:
            await june_link.click()
            await page.wait_for_load_state('networkidle')
        else:
            # If link not found, try to find it relative to the archives element
            june_link_relative = archives_element.get_by_role('link', name='June 2024', exact=False)
            if await june_link_relative.count() > 0:
                await june_link_relative.click()
                await page.wait_for_load_state('networkidle')
            else:
                print("Link for 'June 2024' not found near Archives element.")
    else:
        # If no element with text 'Archives', try to find by role 'complementary' or 'region' that might contain it
        archives_widget = page.get_by_role('complementary', name='Archives', exact=False)
